    const uint32_t BUCKETS = 1048576;     // Stress testing with a high filled ratio at a ~95% filled hash table, expect a very high collision count for both 
    const uint32_t SEED = 547323885;        // Random number generated with "randint(0, (2 ** 32) - 1)" in Python 
    
    printf("HASHES = [");
    
    for (size_t i = 0; i < DATASET_MAX - 1; i++) {      // Generating a list for Python in this loop 
        const char* IT = DATASET[i];
        printf("%llu, ", (unsigned long long)(CAB32_1(IT, strlen(IT), SEED) % BUCKETS));      // murmur3_32((const uint8_t*)IT, strlen(IT), SEED)
    
    }
    
    printf("%llu]\n", (unsigned long long)(CAB32_1(DATASET[DATASET_MAX - 1], strlen(DATASET[DATASET_MAX - 1]), SEED) % BUCKETS));     // murmur3_32((const uint8_t*)(DATASET[DATASET_MAX - 1]), strlen(DATASET[DATASET_MAX - 1]), SEED)
    
    printf("UNIQUE = set(HASHES)\n\nprint(f'Unique indexes: {len(UNIQUE)}')\n");
    
